    isBlank,
    sum,
    count,
    countUnique,
    average,
    stdev,
    min,
    max,
    concat,
    toText,
    len,
    trim,
    upper,
    lower,
    left,
    right,
    mid,
    substitute,
    find,
    search,
    split,
    splitText,
    regexMatch,
    regexReplace,
    regexExtract,
    jsonEscape,
    jsonUnescape,
    repeat,
    round,
    power,
    sqrt,
    toNumber,
    uuid,
    now,
